namespace Inventory;

/// <summary>
/// Runs cycle counts, reconciles discrepancies and updates valuations.
/// </summary>
public sealed class CycleCountService
{
    private readonly CycleCountOperations _operations = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        return _operations.RecordCount(item, warehouse, counted);
    }

    public int CountVariance(StockItem item)
    {
        return _operations.CountVariance(item);
    }

    public string Reconcile(StockItem item)
    {
        return _operations.Reconcile(item);
    }

    public bool FlagDiscrepancy(StockItem item, string reason)
    {
        return _operations.FlagDiscrepancy(item, reason);
    }

    public decimal UpdateValuation(StockItem item, decimal unitCost)
    {
        return _operations.UpdateValuation(item, unitCost);
    }

    private sealed class CycleCountOperations
    {
        private readonly RecordCountOperation _recordCount;
        private readonly VarianceOperation _variance;
        private readonly ReconciliationOperation _reconciliation;
        private readonly DiscrepancyOperation _discrepancy;
        private readonly ValuationOperation _valuation;

        public CycleCountOperations()
        {
            var counts = new CountLedger();
            var discrepancies = new DiscrepancyLedger();
            var valuations = new ValuationLedger();

            _recordCount = new RecordCountOperation(counts, valuations);
            _variance = new VarianceOperation(counts);
            _reconciliation = new ReconciliationOperation(discrepancies);
            _discrepancy = new DiscrepancyOperation(discrepancies);
            _valuation = new ValuationOperation(valuations);
        }

        public string RecordCount(StockItem item, Warehouse warehouse, int counted)
        {
            return _recordCount.Execute(item, warehouse, counted);
        }

        public int CountVariance(StockItem item)
        {
            return _variance.Calculate(item);
        }

        public string Reconcile(StockItem item)
        {
            return _reconciliation.Execute(item);
        }

        public bool FlagDiscrepancy(StockItem item, string reason)
        {
            return _discrepancy.Flag(item, reason);
        }

        public decimal UpdateValuation(StockItem item, decimal unitCost)
        {
            return _valuation.Update(item, unitCost);
        }
    }

    private sealed class RecordCountOperation
    {
        private readonly CountLedger _counts;
        private readonly ValuationLedger _valuations;

        public RecordCountOperation(CountLedger counts, ValuationLedger valuations)
        {
            _counts = counts;
            _valuations = valuations;
        }

        public string Execute(StockItem item, Warehouse warehouse, int counted)
        {
            if (string.IsNullOrEmpty(item.Sku))
                return "no sku";
            if (counted < 0)
                return "invalid";
            if (string.IsNullOrEmpty(warehouse.Code))
                return "no warehouse";

            _counts.Set(item.Sku, counted);
            var variance = counted - item.OnHand;

            if (variance == 0)
                return "match";

            if (variance > 0)
                _valuations.Set(item.Sku, variance * 2.0m);
            else
                _valuations.Set(item.Sku, variance * 1.0m);

            if (variance > 100 || variance < -100)
                return "large variance";
            if (counted == 0 && item.OnHand > 0)
                return "zeroed";
            return "recorded";
        }
    }

    private sealed class VarianceOperation
    {
        private readonly CountLedger _counts;

        public VarianceOperation(CountLedger counts)
        {
            _counts = counts;
        }

        public int Calculate(StockItem item)
        {
            if (string.IsNullOrEmpty(item.Sku))
                return 0;
            if (!_counts.TryGet(item.Sku, out var counted))
                return 0;

            var variance = counted - item.OnHand;
            if (variance == 0)
                return 0;
            if (variance > 1000)
                return 1000;
            if (variance < -1000)
                return -1000;
            if (variance > 0 && counted > item.OnHand * 2)
                return variance + 1;
            if (variance < 0)
                return variance;
            return variance;
        }
    }

    private sealed class ReconciliationOperation
    {
        private readonly DiscrepancyLedger _discrepancies;

        public ReconciliationOperation(DiscrepancyLedger discrepancies)
        {
            _discrepancies = discrepancies;
        }

        public string Execute(StockItem item)
        {
            if (string.IsNullOrEmpty(item.Sku))
                return "no sku";

            int available = item.OnHand - item.Reserved;
            if (available < 0)
            {
                _discrepancies.Add($"{item.Sku}:oversold");
                return "oversold";
            }
            if (item.Reserved < 0)
            {
                _discrepancies.Add($"{item.Sku}:negative-reserve");
                return "bad reserve";
            }
            if (item.OnHand == 0 && item.Reserved > 0)
            {
                _discrepancies.Add($"{item.Sku}:phantom-reserve");
                return "phantom";
            }
            if (available > 0 && available < 5)
                _discrepancies.Add($"{item.Sku}:low");
            else if (available > 10000)
                _discrepancies.Add($"{item.Sku}:excess");

            if (_discrepancies.Count > 1000)
                return "too many discrepancies";
            return "reconciled";
        }
    }

    private sealed class DiscrepancyOperation
    {
        private readonly DiscrepancyLedger _discrepancies;

        public DiscrepancyOperation(DiscrepancyLedger discrepancies)
        {
            _discrepancies = discrepancies;
        }

        public bool Flag(StockItem item, string reason)
        {
            if (string.IsNullOrEmpty(item.Sku))
                return false;
            if (string.IsNullOrEmpty(reason))
                return false;
            if (reason.Length > 200)
                reason = reason.Substring(0, 200);
            if (_discrepancies.Count > 5000)
                return false;

            string tag;
            if (reason.StartsWith("oversold", StringComparison.Ordinal))
                tag = "critical";
            else if (reason.StartsWith("low", StringComparison.Ordinal))
                tag = "warn";
            else if (reason.StartsWith("excess", StringComparison.Ordinal))
                tag = "info";
            else
                tag = "note";

            _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
            if (tag == "critical" && _discrepancies.Count > 0)
                return true;
            return tag != "note";
        }
    }

    private sealed class ValuationOperation
    {
        private readonly ValuationLedger _valuations;

        public ValuationOperation(ValuationLedger valuations)
        {
            _valuations = valuations;
        }

        public decimal Update(StockItem item, decimal unitCost)
        {
            if (string.IsNullOrEmpty(item.Sku))
                return 0m;
            if (unitCost < 0m)
                return 0m;

            int basisQty;
            if (item.ReorderPoint > 0 && item.OnHand > item.ReorderPoint)
                basisQty = item.OnHand;
            else if (item.OnHand > 0)
                basisQty = item.OnHand;
            else
                basisQty = 0;

            decimal value = basisQty * unitCost;
            if (value > 1_000_000m)
                value = 1_000_000m;
            else if (value < 0m)
                value = 0m;

            _valuations.Set(item.Sku, value);
            if (basisQty == 0 || unitCost == 0m)
                return 0m;
            return value;
        }
    }

    private sealed class CountLedger
    {
        private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);

        public void Set(string sku, int counted)
        {
            _counts[sku] = counted;
        }

        public bool TryGet(string sku, out int counted)
        {
            return _counts.TryGetValue(sku, out counted);
        }
    }

    private sealed class DiscrepancyLedger
    {
        private readonly List<string> _entries = new();

        public int Count => _entries.Count;

        public void Add(string discrepancy)
        {
            _entries.Add(discrepancy);
        }
    }

    private sealed class ValuationLedger
    {
        private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

        public void Set(string sku, decimal value)
        {
            _valuations[sku] = value;
        }
    }
}
